import { useEffect, useState } from 'react'
import { Plus, Search } from 'lucide-react'
import { catalogApi, type Category, type Product, type Vendor } from '../../api'
import { Button } from '../../components/ui/button'
import { Card, CardContent } from '../../components/ui/card'
import { Input } from '../../components/ui/input'

export function CatalogPage({ vendor }: { vendor?: Vendor }) { const [products, setProducts] = useState<Product[]>([]); const [categories, setCategories] = useState<Category[]>([]); const [search, setSearch] = useState(''); const [categoryName, setCategoryName] = useState(''); const [message, setMessage] = useState(''); function load() { if (!vendor) return; catalogApi.products(vendor.id, search).then(setProducts).catch(() => setProducts([])); catalogApi.categories(vendor.id).then(setCategories).catch(() => setCategories([])) } useEffect(load, [vendor, search]); async function createCategory() { if (!vendor || !categoryName.trim()) return; try { await catalogApi.createCategory(vendor.id, categoryName); setCategoryName(''); load() } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to create category.') } } return <><PageIntro title="Catalog" text="Organize products, categories, prices, unit types, and barcodes." />{message && <p className="mb-4 rounded-xl bg-rose-50 p-3 text-sm text-rose-700">{message}</p>}<div className="grid gap-5 xl:grid-cols-[1fr_300px]"><Card><CardContent className="p-4"><div className="relative mb-4"><Search className="absolute left-3 top-3 text-slate-400" size={16} /><Input className="pl-9" placeholder="Search product or SKU" value={search} onChange={event => setSearch(event.target.value)} /></div><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b border-slate-100 text-xs uppercase text-slate-500"><tr><th className="px-3 py-3">Product</th><th className="px-3 py-3">Category</th><th className="px-3 py-3">Unit</th><th className="px-3 py-3">Retail</th><th className="px-3 py-3">Barcode</th></tr></thead><tbody>{products.map(product => <tr key={product.id} className="border-b border-slate-50"><td className="px-3 py-3 font-semibold">{product.name}<small className="block text-xs text-slate-400">{product.sku}</small></td><td className="px-3 py-3 text-slate-500">{product.categoryName ?? 'Uncategorized'}</td><td className="px-3 py-3 text-slate-500">{product.unitType}</td><td className="px-3 py-3">PHP {product.retailPrice.toLocaleString()}</td><td className="px-3 py-3 text-xs text-slate-500">{product.barcodes.join(', ') || '—'}</td></tr>)}</tbody></table>{!products.length && <p className="p-8 text-center text-sm text-slate-500">No products found.</p>}</div></CardContent></Card><Card><CardContent className="p-5"><h2 className="font-bold">Categories</h2><div className="mt-3 flex gap-2"><Input placeholder="New category" value={categoryName} onChange={event => setCategoryName(event.target.value)} /><Button size="sm" onClick={createCategory}><Plus size={15} /></Button></div><div className="mt-4 flex flex-wrap gap-2">{categories.map(category => <span key={category.id} className="rounded-full bg-indigo-50 px-3 py-1.5 text-xs font-semibold text-indigo-700">{category.name}</span>)}</div></CardContent></Card></div></> }

function PageIntro({ title, text }: { title: string; text: string }) { return <div className="mb-6"><p className="text-[11px] font-bold uppercase tracking-[.17em] text-indigo-600">Product management</p><h1 className="mt-1.5 text-3xl font-black tracking-[-.055em]">{title}</h1><p className="mt-2 text-[13px] text-slate-500">{text}</p></div> }
